import java.util.*;

class Solution {
  public String longestWord(String[] words) {
    Arrays.sort(words, (a, b) -> a.length() != b.length() ? a.length() - b.length() : a.compareTo(b));
    Set<String> good = new HashSet<>(); // words whose every prefix is a word
    String best = "";
    for (String w : words) {
      if (w.length() == 1 || good.contains(w.substring(0, w.length() - 1))) {
        good.add(w);
        if (w.length() > best.length()) best = w; // shorter-first, then lexicographic, so the first longest wins
      }
    }
    return best;
  }
}
